programs.haiku:
"""Relative-clause openers: a wh-word that begins a relative clause pushes this
component negative, most of all right after a comma or bracket ("..., which ...",
"..., who ..."). The effect carries over the next two tokens, the clause's first words
("which *is*", "who *was*"), then fades. Elsewhere the component sits near zero.

Everything else in its activation (most of the variance) is diffuse and not
predictable from the words alone, so this program only captures the relative-clause
openers.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Typical value at a relative pronoun, by word (negative = the component's firing sign).
WH_VALUE = {"which": -1.0, "whom": -0.9, "who": -0.6, "whose": -0.6, "where": -0.3}

# A wh-word right after one of these opens a non-restrictive clause: stronger.
OPENERS = {",", ";", "(", "[", "–", "—", '"', "“"}
BOOST = 1.2

# "what" after "is" or "'s" ("exactly what we found") behaves like a relative word.
WHAT_VALUE = -0.9
COPULAS = {"is", "'s", "’s"}

# Share of a trigger's value carried by the token itself, then the next two tokens.
TAIL = (1.0, 0.4, 0.13)


def _word(prefix, i: int) -> str:
    return prefix.token_strings[i].strip().lower()


def _trigger(prefix, i: int) -> float:
    """How strongly the token at position i opens a relative clause (0 if it does not)."""
    word = _word(prefix, i)
    value = WH_VALUE.get(word, 0.0)
    if word == "what" and i > 0 and _word(prefix, i - 1) in COPULAS:
        value = WHAT_VALUE
    if value and i > 0 and prefix.document_ids[i - 1] == prefix.document_ids[i]:
        if prefix.token_strings[i - 1].strip() in OPENERS:
            value *= BOOST
    return value


def step(carry, prefix, upstream: Mapping):
    t = prefix.position
    total = 0.0
    # A trigger at t-k, in the same document, still shows up at t with weight TAIL[k].
    for k, share in enumerate(TAIL):
        i = t - k
        if i < 0 or prefix.document_ids[i] != prefix.document_ids[t]:
            break
        total += share * _trigger(prefix, i)
    return carry, float(total)

"""Layer 15 MLP down_proj, component 3338: a "direct object is coming" detector.

It is positive on the word "of" (and Spanish/French "de"), the strongest case, when
"of" follows a noun such as "sum of", "transfer of" or "measure of" (it introduces
the object of an action or quantity). It is weaker after fixed phrases like "out of",
"instead of", "kind of" or "capable of".

It is also positive on action verbs (solve, remove, buy, detect, ...), most strongly
when the verb follows "to" or a modal ("to solve", "can remove"), and on the "-ing"
suffix piece. Intransitive or participle-like words (go, based, known) stay near zero.

It is negative on prepositions, conjunctions and articles ("to", "by", "from", "as",
"in", "the", "and"), which introduce a phrase rather than an object. Everything else is 0.

The program reads only the current token and the one before it, so it is causal.
"""
from functools import lru_cache

import wordnet

READS = ()

OF_WORDS = {"of", "de"}
PHRASAL_BEFORE_OF = {"out", "instead", "because", "kind", "instance", "capable", "front", "way", "terms"}
MODALS = {"to", "can", "will", "should", "must", "could", "would", "may", "might"}
PREPOSITIONS = {"to", "by", "from", "as", "in", "for", "with", "on", "at", "that", "and", "or", "the", "a", "an"}


@lru_cache(maxsize=None)
def is_verb(word):
    return "verb" in wordnet.parts_of_speech(word)


@lru_cache(maxsize=None)
def is_only_verb(word):
    pos = wordnet.parts_of_speech(word)
    return "verb" in pos and not ({"noun", "adjective", "adverb"} & pos)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    before = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    if token.startswith(" ") and word.lower() in OF_WORDS:
        value = 0.7 if before.lower() in PHRASAL_BEFORE_OF else 2.6
    elif word.isalpha() and word.islower() and len(word) > 2 and is_verb(word):
        if before in MODALS:
            value = 1.9
        elif is_only_verb(word):
            value = 0.8
        else:
            value = 0.1
    elif token == "ing":
        value = 1.3
    elif token.startswith(" ") and word in PREPOSITIONS:
        value = -0.2
    else:
        value = 0.0
    return carry, value


def main():
    """Print the program's value for a few example tokens after 'to' or 'of'."""
    for token in [" solve", " of", " based", " the"]:
        print(repr(token), step(None, _Prefix([" to", token]), {})[1])


class _Prefix:
    def __init__(self, token_strings):
        self.token_strings = token_strings


if __name__ == "__main__":
    main()

"""Final noun of a modified noun phrase, in running English text.

Plain-terms summary: this component is strongly positive on a content noun that
follows other nouns or adjectives, so it closes a compound noun phrase ("disk
[cache]", "Document Manager [service]", "serum glucose [levels]"). A noun
standing alone is weakly positive; a noun right after a determiner or quantifier
("each", "several", "all") is slightly negative. Hyphenated suffixes such as
"-based", "-related" and "-free" are negative.

This is only a partial explanation. The component's activation varies a lot
between occurrences of the same word, and the words and their neighbours explain
only a few percent of the variance; the rules below capture the main lexical
trend, not the bulk of it.
"""

from functools import lru_cache

from wordnet import parts_of_speech

READS = ()

DETERMINERS = frozenset(
    """the a an this that these those each every all some any no many several
    various multiple few most other such both two three four five six its their
    his her our your my new old certain different recent entire single particular
    great own same first second last next""".split()
)


@lru_cache(maxsize=None)
def is_word(token):
    """An English word of three or more letters, with or without its leading space."""
    w = token.strip()
    return w.isascii() and w.isalpha() and len(w) >= 3


@lru_cache(maxsize=None)
def is_noun(token):
    return is_word(token) and "noun" in parts_of_speech(token.strip().lower())


@lru_cache(maxsize=None)
def is_modifier(token):
    """A noun or an adjective: a word that can sit in front of a head noun."""
    return is_word(token) and bool({"noun", "adjective"} & parts_of_speech(token.strip().lower()))


def is_suffix(token):
    """A hyphenated suffix token, such as '-based'."""
    w = token[1:]
    return token.startswith("-") and w.isascii() and w.isalpha()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    # carry = (document, run of modifiers ending at the previous token, previous token is a determiner)
    if carry is not None and carry[0] == doc:
        run, after_det = carry[1], carry[2]
    else:
        run, after_det = 0, False
    if is_noun(token):
        if run >= 2:
            value = 1.0
        elif run == 1:
            value = 0.45
        elif after_det:
            value = -0.1
        else:
            value = 0.1
    elif is_suffix(token):
        value = -0.25
    else:
        value = 0.0
    new_run = run + 1 if is_modifier(token) else 0
    new_carry = (doc, new_run, token.strip().lower() in DETERMINERS)
    return new_carry, value

"""Layer 15 MLP down_proj component 3359: a diffuse, weakly token-dependent write.

Its activation is small and noisy (mean 0.02, std 0.27). It is not tied to any
word or position we could find. Grouping the current token by script and
shape explains about half a percent of its variance. The first token of each
document gets almost nothing, about 0. So the program predicts a small value
by token class, and 0 at each document's first token.
"""

import re

READS = ()

# Mean activation of the token classes, measured on training rows.
CLASS_MEAN = {
    "kana": 0.07,
    "cyrillic": 0.05,
    "han": 0.04,
    "space_word": 0.035,
    "word": 0.02,
    "digit": -0.02,
    "other": 0.0,
}


def token_class(text):
    if "�" in text or not text.strip():
        return "other"
    if re.search(r"[぀-ヿ]", text):
        return "kana"
    if re.search(r"[Ѐ-ӿ]", text):
        return "cyrillic"
    if re.search(r"[一-鿿]", text):
        return "han"
    if re.fullmatch(r" [A-Za-z]+", text):
        return "space_word"
    if re.fullmatch(r"[A-Za-z]+", text):
        return "word"
    if re.fullmatch(r"\s*[0-9]+\s*", text):
        return "digit"
    return "other"


def step(carry, prefix, upstream):
    ids = prefix.document_ids
    if len(ids) == 1 or ids[-1] != ids[-2]:
        return carry, 0.0
    return carry, CLASS_MEAN[token_class(prefix.token_strings[-1])]

"""Ordering and sign talk: an MLP unit that lights up on inequality operators and
comparison words, where a text states that one quantity is bigger, smaller,
positive, negative, or on one side of a bound.

Activation rule (a readable approximation, fit on training rows):
  - an inequality operator (<, >, <=, >=, and the unicode ≤ ≥) predicts 1.0,
    or 2.0 when it comes right after a number ("0 < x", "8 <= n");
  - a comparison word (than, less, greater, smaller, bigger, larger, exceeds,
    above, below, beyond) predicts 0.7;
  - a sign or bound word (positive, negative, between, threshold, inequality)
    predicts 0.5;
  - a word or operator that comes after an ordering token earlier in the same
    sentence gets a small 0.1 boost; the sentence state resets at each sentence
    break and at each new document.
Everything else predicts 0. Arrows (=>), HTML tags and other operators are not
counted, since they do not state an ordering.

What it leaves out: most of the variance is in rare, very large spikes inside
long sign-analysis passages (root-finding, "f(x) is negative, so there is a
root between"), which depend on the wider reasoning and not on any single
token. This program explains only about 1% of the variance on eval rows. A
per-token lookup table explains less, so the ordering concept is the best simple
handle found.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

INEQUALITY = {"<", ">", "<=", ">=", "≤", "≥"}
COMPARE = {"than", "less", "greater", "smaller", "bigger", "larger", "exceeds", "above", "below", "beyond"}
SIGN = {"positive", "negative", "between", "threshold", "inequality"}
SENTENCE_END = {".", "?", "!"}


def _word(token: str) -> str:
    return "".join(ch for ch in token.lower() if ch.isalpha())


def step(carry, prefix, upstream: Mapping):
    # carry: (document label, whether an ordering token already appeared in this sentence)
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        seen = False
    else:
        seen = carry[1]
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = _word(token)
    if token in INEQUALITY:
        # an operator right after a number ("8 <= n", "0 < x") fires harder
        before = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
        value = 2.0 if any(ch.isdigit() for ch in before) else 1.0
    elif word in COMPARE:
        value = 0.7
    elif word in SIGN:
        value = 0.5
    else:
        value = 0.0
    if value > 0 and seen:
        value += 0.1
    # Update the sentence state for the next token.
    if token in SENTENCE_END or "\n" in raw:
        seen = False
    elif value > 0:
        seen = True
    return (doc, seen), float(value)

"""Layer-15 MLP neuron 3376 (down_proj component 3376): a "how big / how many" detector.

The component reads one MLP hidden unit (3376) and writes the word "length / size"
toward the output (its output direction promotes len, length, size, ...). It is
active on words that name how big something is or how many there are:

- code identifiers for lengths and sizes, strongest when reached through a dot,
  underscore or open paren (`arr.size`, `s.length`, `len(`, `_count`, `.Height`);
- the bare loop-bound variables n, m, k, mainly right after `<`, `<=`, `(` or `int`
  (`for (i = 0; i < n`, `int n`);
- quantity words in prose (number, total, many, pages, digits, rows, population);
- the token right after a size word, weakly.

Everything else, including digits, is predicted as 0. Only the current token and the
one before it are read; the rest of the context is ignored.
"""

import re

READS = ()

SIZE_WORDS = {"len", "length", "size", "count", "num", "height", "width", "cnt"}
LOOP_VARS = {"n", "m", "k"}
QUANTITY_WORDS = {
    "number", "total", "many", "pages", "digits", "rows", "lines", "words",
    "population", "amount",
}
BEFORE_BOUND = {"<", "<=", ">", ">=", "int", "("}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    word = re.sub(r"[^A-Za-z]", "", tok).lower()
    prev_word = re.sub(r"[^A-Za-z]", "", prev).lower()
    if word in SIZE_WORDS:
        return carry, 9.0 if tok[:1] in "._(" else 3.5
    if word in LOOP_VARS and len(word) == 1:
        return carry, 1.7 if prev in BEFORE_BOUND else 0.4
    if word in QUANTITY_WORDS:
        return carry, 1.1
    if prev_word in SIZE_WORDS:
        return carry, 1.0
    return carry, 0.0
